import { ISongReference } from './song-reference.interface';

/**
 * A schedule reference auto-generated by the app (e.g. a Spotify playlist
 * created from a schedule). Extends ISongReference with sync metadata that
 * tracks the state of the generated artifact.
 */
export interface ISchedulePlaylistReference extends ISongReference {
  /** Which app feature generated this reference. */
  source: 'spotify-auto' | 'youtube-auto'
  syncedAt?: string
  tracksHash?: string
  syncedBy?: number
  syncedByName?: string
  /** Computed by the API for the requesting user. */
  syncedByMe?: boolean
}
